import React from 'react';
import { Lock, Users, Video, CheckCircle2 } from 'lucide-react';

const features = [
  {
    icon: Lock,
    title: 'End-to-End Encryption',
    desc: "Your personal messages and calls are secured. Only you and the person you're talking to can read or listen to them.",
  },
  {
    icon: Users,
    title: 'Group Chats',
    desc: 'Keep in touch with the groups of people that matter the most, like your family or coworkers, in organized channels.',
  },
  {
    icon: Video,
    title: 'Voice & Video Calls',
    desc: 'Make secure, high-quality voice and video calls for free, anywhere in the world, on any device.',
  },
];

const checkpoints = [
  'Real-time synchronization',
  'Offline message queuing',
  'Native desktop applications',
];

export default function ConnectSection() {
  return (
    <>
      {/* ── Section 1: Everything you need to connect ── */}
      <section className="py-20 bg-sky-50/50 border-t border-sky-100/60">
        <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12">
          {/* Header */}
          <div className="text-center max-w-2xl mx-auto space-y-3 mb-14">
            <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight">
              Everything you need to connect
            </h2>
            <p className="text-sm sm:text-base text-slate-500 leading-relaxed">
              Built for performance and security, providing a seamless communication workspace.
            </p>
          </div>

          {/* Feature Cards Grid */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {features.map(({ icon: Icon, title, desc }) => (
              <div
                key={title}
                className="bg-white rounded-2xl border border-slate-100 p-8 hover:shadow-lg hover:-translate-y-1 transition-all duration-300 group"
              >
                {/* Icon Box */}
                <div className="w-11 h-11 rounded-xl bg-sky-50 border border-sky-100 flex items-center justify-center mb-6 group-hover:bg-[#006699] group-hover:border-[#006699] transition-all duration-300">
                  <Icon className="w-5 h-5 text-sky-600 group-hover:text-white transition-colors duration-300" />
                </div>
                <h3 className="text-base font-bold text-slate-900 mb-2">{title}</h3>
                <p className="text-sm text-slate-500 leading-relaxed">{desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── Section 2: Seamless across all your devices ── */}
      <section className="py-20 bg-gradient-to-br from-sky-50 via-blue-50/40 to-slate-50 border-t border-sky-100/60">
        <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-16 items-center">
            {/* Left: Text Content */}
            <div className="space-y-6 max-w-lg">
              <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight leading-tight">
                Seamless across all your devices
              </h2>
              <p className="text-sm sm:text-base text-slate-600 leading-relaxed">
                Sync your chats across mobile, web, and desktop. Start a conversation on your phone and finish it on your laptop without missing a beat.
              </p>

              {/* Checkpoint List */}
              <ul className="space-y-3 pt-2">
                {checkpoints.map((point) => (
                  <li key={point} className="flex items-center gap-3">
                    <CheckCircle2 className="w-5 h-5 text-sky-600 shrink-0" />
                    <span className="text-sm text-slate-700 font-medium">{point}</span>
                  </li>
                ))}
              </ul>
            </div>

            {/* Right: Devices Image */}
            <div className="relative flex justify-center items-center">
              {/* Glow behind image */}
              <div className="absolute inset-0 bg-sky-200/30 rounded-3xl blur-3xl pointer-events-none"></div>

              <div className="relative rounded-3xl overflow-hidden shadow-2xl shadow-slate-900/10 border border-white/80">
                <img
                  src="https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&q=80&w=900"
                  alt="WhatsApp on laptop and mobile devices"
                  className="w-full h-full object-cover max-h-72 lg:max-h-80"
                />
                {/* Overlay tint to match the screenshot's blue-ish tone */}
                <div className="absolute inset-0 bg-sky-900/5 pointer-events-none"></div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
